import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true, // Slider altındaki noktalar
    infinite: true, // Sonsuz kaydırma
    speed: 500, // Kaydırma hızı
    slidesToShow: 1, // Bir seferde gösterilecek slide sayısı
    slidesToScroll: 1, // Her kaydırmada kaç slide kaydırılacak
    arrows: true, // Ok işaretlerinin görünmesini sağla
  };

  return (
    <div
      style={{
        position: "relative",
        width: "1024px",
        height: "394,42px",
        margin: "0 auto",
        background: "#293349", // Lacivert arka plan
        border: "15px solid #00C26D", // Yeşil çerçeve
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        padding: "0",
        gap: "4px",
      }}
    >
      {/* Slider İçeriği */}
      <Slider {...settings}>
        <div
          style={{
            height: "373px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 1
        </div>
        <div
          style={{
            height: "373px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 2
        </div>
        <div
          style={{
            height: "373px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 3
        </div>
      </Slider>

      {/* Kesik Çizgiler ve Dots */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          display: "flex",
          flexDirection: "column",
          gap: "10px",
        }}
      >
        {/* Dotlar */}
        <div
          style={{
            width: "30.16px",
            height: "11.11px",
            background: "#293349",
          }}
        ></div>
        <div
          style={{
            width: "30.16px",
            height: "11.11px",
            background: "#293349",
          }}
        ></div>
      </div>
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          display: "flex",
          flexDirection: "row",
          gap: "10px",
        }}
      >
        {/* Kesik Çizgi */}
        <div
          style={{
            width: "142.57px",
            height: "17.42px",
            background: "#293349",
          }}
        ></div>
      </div>
    </div>
  );
};

export default EventsSlider;
